//! # Wynxer
//!
//! A Lynxer-like language for the web. Wynxer compiles to JavaScript and
//! WebAssembly for logic, and to HTML and CSS for presentation. Pages are
//! written in `.wpf` (Wynxer Page Format), a very simplified DSL, so the
//! author never has to write HTML directly.
//!
//! Wynxer is a separate binary from `lynxer` and ships its own version
//! (0.1.0). Everything is generated by the Rust backend.

pub mod ast;
pub mod build;
pub mod cli;
pub mod diagnostic;
pub mod format;
pub mod init;
pub mod ir;
pub mod jsabi;
pub mod lint;
pub mod lexer;
pub mod parser;
pub mod project;
pub mod wpf;

pub mod backend {
    pub mod css;
    pub mod html;
    pub mod js;
    pub mod wasm;
}

/// The version of Wynxer, sourced from Cargo.toml.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");
/// The name of the executable.
pub const NAME: &str = "wynxer";

/// Run the Wynxer CLI. Returns the process exit code.
pub fn run() -> i32 {
    cli::run()
}
